import Accessibility
import AVFoundation
import UIKit

/// A's announcement queue wraps B's Speaker for VoiceOver compatibility (A90/A77):
/// - With VoiceOver, post lower-priority accessibility announcements instead of overlapping two voices.
/// - Following 2026-10-12 feedback, new speech replaces old speech once the current utterance exceeds burstWindow.
///   Stop the outdated utterance and clear its queue so new-screen/action results are spoken promptly.
/// - Utterances generated by the same action within burstWindow remain sequential.
/// - interrupt() stops and clears speech on tab/card/settings/onboarding/background transitions via AppStore.hush().
/// - Informational speech queued over six seconds expires; its visual text remains.
/// - Prompts requiring a response clear older informational items and are never displaced by them.
/// - Defer announcements while listening to avoid stealing the microphone or recording synthesized speech.
/// - Disabling automatic speech still permits VoiceOver and explicit forced replay.
/// AppStore calls say(); other callers must not bypass the wrapper with speaker.speak.
@MainActor
final class Announcer {
    /// prompt requires a user decision; info merely provides information.
    enum Kind { case info, prompt }

    struct Line: Equatable {
        var text: String
        var kind: Kind
        var at: Date
        /// An explicit replay request speaks even when automatic announcements are disabled.
        var force = false
    }

    /// Bound queue length, discarding the oldest informational item first.
    static let maxQueued = 3
    /// New utterances within this action-burst interval queue without interrupting.
    static let burstWindow: TimeInterval = 0.5
    /// Expire informational items after this queue age.
    static let staleAfter: TimeInterval = 6

    private var queue: [Line] = []
    private var held: [Line] = []
    private var pump: Task<Void, Never>?
    /// Current Announcer-started utterance and its start time.
    private var current: (line: Line, at: Date)?

    /// Use accessibility announcements when VoiceOver is running; overridable in tests.
    var voiceOverRunning: () -> Bool = { UIAccessibility.isVoiceOverRunning }
    /// Injectable clock for tests.
    var clock: () -> Date = { Date() }
    /// Test override for synthesizer speaking/finished state; nil uses the real synthesizer.
    var busy: (() -> Bool)?

    func say(_ text: String, kind: Kind = .info, force: Bool = false, via speaker: Speaker, holding: Bool) {
        guard !text.isEmpty else { return }
        enqueue(Line(text: text, kind: kind, at: clock(), force: force), via: speaker, holding: holding)
    }

    /// Enqueue deferred listening-time speech with its original timestamp so expiry still applies.
    func enqueue(_ line: Line, via speaker: Speaker, holding: Bool) {
        if holding { held.append(line); return }
        if isStale(line) { return }
        if voiceOverRunning() { announce(line.text, speaker); return }
        if !line.force && !speaker.settings.enabled { return }
        let speaking = isSpeaking(speaker)
        if !speaking { current = nil }
        // Replace an already-running older action's speech immediately when outside the burst window.
        if speaking, current.map({ clock().timeIntervalSince($0.at) >= Self.burstWindow }) ?? true {
            interrupt(speaker)
            speakNow(line, speaker)
            return
        }
        // Do not queue a decision prompt behind stale information.
        if line.kind == .prompt { queue.removeAll { $0.kind == .info } }
        if queue.isEmpty && !speaking {
            speakNow(line, speaker)
            return
        }
        queue.append(line)
        while queue.count > Self.maxQueued {
            if let i = queue.firstIndex(where: { $0.kind == .info }) { queue.remove(at: i) } else { queue.removeFirst() }
        }
        drain(speaker)
    }

    /// On listening start, stop current speech but retain pending items until microphone release.
    func hold(_ speaker: Speaker) {
        held = queue + held
        queue = []
        pump?.cancel()
        pump = nil
        current = nil
        speaker.stop()
    }

    /// On screen change/cancellation, stop and clear current, queued, and listening-deferred speech.
    func interrupt(_ speaker: Speaker) {
        queue = []
        held = []
        pump?.cancel()
        pump = nil
        current = nil
        speaker.stop()
    }

    /// On microphone release, return deferred items for the caller to enqueue after its response.
    func release() -> [Line] {
        defer { held = [] }
        return held
    }

    /// Pending utterances exposed for tests.
    var queued: [Line] { queue }
    var pendingCount: Int { queue.count + held.count }

    // MARK: - Internal helpers

    private func isStale(_ line: Line) -> Bool {
        line.kind == .info && clock().timeIntervalSince(line.at) > Self.staleAfter
    }

    private func announce(_ text: String, _ speaker: Speaker) {
        var a = AttributedString(text)
        a.languageIdentifier = speaker.settings.language.bcp47
        a.accessibilitySpeechAnnouncementPriority = .low
        AccessibilityNotification.Announcement(a).post()
    }

    private func speakNow(_ line: Line, _ speaker: Speaker) {
        current = (line, clock())
        speaker.speak(line.text)
    }

    private func drain(_ speaker: Speaker) {
        guard pump == nil else { return }
        pump = Task { @MainActor [weak self] in
            while let self, !Task.isCancelled, !self.queue.isEmpty {
                if self.isSpeaking(speaker) {
                    try? await Task.sleep(for: .milliseconds(150))
                    continue
                }
                if self.voiceOverRunning() {
                    self.queue.filter { !self.isStale($0) }.forEach { self.announce($0.text, speaker) }
                    self.queue = []
                    break
                }
                let line = self.queue.removeFirst()
                if self.isStale(line) || (!line.force && !speaker.settings.enabled) { continue }
                self.speakNow(line, speaker)
                try? await Task.sleep(for: .milliseconds(300))
            }
            self?.pump = nil
        }
    }

    private func isSpeaking(_ speaker: Speaker) -> Bool {
        if let busy { return busy() }
        return speaker.isSpeaking
    }
}
